    {
      "hunk_id": "H093",
      "decision": "SOL",
      "reason": "SOL keeps Hong Dao’s usually amiable manner and the seriousness of his words."
    },
    {
      "hunk_id": "H094",
      "decision": "SOL",
      "reason": "SOL preserves the friend’s voice remaining audible beneath the blast."
